  // Status mapping labels and styles
  const getStatusLabel = (status: QuotationStatus) => {
    const labels: Record<QuotationStatus, string> = {
      pending: 'æœªå ±åƒ¹',
      quoted: 'å ±åƒ¹å¾…å›è¦†',
      signed: 'å·²ç°½ç´„',
      constructing: 'æ–½å·¥ä¸­',
      finished: 'æ–½å·¥å®Œæˆ',
      completed: 'å®Œå·¥çµæ¸…',
      cancelled: 'ä½œå»¢'
    };
    return labels[status] || status;
  };

  const getStatusStyle = (status: QuotationStatus) => {
    const styles: Record<QuotationStatus, { bg: string, text: string }> = {
      pending: { bg: 'bg-gray-100', text: 'text-gray-700' },
      quoted: { bg: 'bg-amber-100', text: 'text-amber-800' },
      signed: { bg: 'bg-emerald-100', text: 'text-emerald-800' },
      constructing: { bg: 'bg-blue-100', text: 'text-blue-800' },
      finished: { bg: 'bg-indigo-100', text: 'text-indigo-800' },
      completed: { bg: 'bg-purple-100', text: 'text-purple-800' },
      cancelled: { bg: 'bg-rose-100', text: 'text-rose-800' }
    };
    return styles[status] || { bg: 'bg-gray-100', text: 'text-gray-700' };
  };

  // --- GET PAYMENT STAGES DYNAMICALLY ---
  const getPaymentStages = (quote: Quotation): PaymentStage[] => {
    if (quote.paymentStages && quote.paymentStages.length > 0) {
      return quote.paymentStages;
    }
    return [
      { name: 'ç¬¬ä¸€æœŸ', percent: 35, remark: 'ç°½ç´„åŠé€²å ´å‰' },
      { name: 'ç¬¬äºŒæœŸ', percent: 20, remark: 'å®Œæˆæ°´ã€é›»ã€æ‰¹ç›ªã€é˜²æ°´ã€è©¦æ°´48å°æ™‚' },
      { name: 'ç¬¬ä¸‰æœŸ', percent: 15, remark: 'å®Œæˆå…¨éƒ¨ç“·ç£šå®‰è£' },
      { name: 'ç¬¬å››æœŸ', percent: 10, remark: 'å‚¢ä¿¬ç¢ºèªæ–½å·¥åœ–' },
      { name: 'ç¬¬äº”æœŸ', percent: 15, remark: 'å‚¢ä¿¬é€è²¨å‰' },
      { name: 'ç¬¬å…­æœŸ', percent: 5, remark: 'å®Œå·¥å¾Œ' }
    ];
  };

  // --- CALCULATE QUOTE FINANCIALS ---
  const getQuoteFinancials = (quote: Quotation) => {
    const roundTo2 = (num: number) => Math.round(num * 100) / 100;
    const subtotal = roundTo2(quote.items.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0));
    const discountsList = quote.enableDiscounts
      ? (quote.discounts && quote.discounts.length > 0
          ? quote.discounts
          : (quote.discount > 0 ? [{ id: 'legacy', amount: quote.discount, targetItemId: quote.discountTargetItemId }] : []))
      : [];
    const totalDiscount = roundTo2(discountsList.reduce((sum, d) => sum + (d.amount || 0), 0));
    
    const deductDeposit = quote.receivedDeposit !== undefined ? Math.max(0, quote.receivedDeposit) : 0;
    const contractTotalBeforeDeposit = Math.max(0, roundTo2(subtotal - totalDiscount));
    const grandTotal = Math.max(0, roundTo2(subtotal - totalDiscount));
    
    // Percentage splits based on contract total
    const depositVal = roundTo2(contractTotalBeforeDeposit * ((quote.depositPercent ?? 30) / 100));
    const progressVal = roundTo2(contractTotalBeforeDeposit * ((quote.progressPercent ?? 50) / 100));
    const balanceVal = roundTo2(contractTotalBeforeDeposit - depositVal - progressVal); 

    // Dynamic payment stages values
    const stages = getPaymentStages(quote);
    const sumAllPercents = stages.reduce((sum, s) => sum + (s.percent || 0), 0) || 100;

    // 1. Calculate un-deducted base value for each stage based on contractTotalBeforeDeposit
    const unadjustedStageBases = stages.map((s) => {
      const baseAlloc = roundTo2(contractTotalBeforeDeposit * (s.percent / sumAllPercents));
      return Math.max(0, roundTo2(baseAlloc + (s.adjustmentAmount || 0)));
    });

    // 2. Handle paid vs unpaid stages & deduct deposit ONLY from first stage (ç¬¬ä¸€æœŸ, index 0)
    const computedValues: number[] = [];
    for (let idx = 0; idx < stages.length; idx++) {
      const s = stages[idx];
      if (idx === 0) {
        // ç¬¬ä¸€æœŸï¼šæ‰£é™¤å®šé‡‘
        const base = unadjustedStageBases[0];
        if (s.isPaid) {
          const lockedVal = s.lockedAmount !== undefined ? s.lockedAmount : Math.max(0, roundTo2(base - deductDeposit));
          computedValues.push(roundTo2(lockedVal));
        } else {
          const val = Math.max(0, roundTo2(base - deductDeposit));
          computedValues.push(roundTo2(val));
        }
      } else {
        // å¾ŒçºŒæœŸæ•¸ï¼šä¸æ‰£é™¤å®šé‡‘
        if (s.isPaid) {
          const lockedVal = s.lockedAmount !== undefined ? s.lockedAmount : unadjustedStageBases[idx];
          computedValues.push(roundTo2(lockedVal));
        } else {
          computedValues.push(roundTo2(unadjustedStageBases[idx]));
        }
      }
    }

    // 3. Reconcile remaining unpaid balance to ensure sum of stage values equals targetStagesTotal (grandTotal - deductDeposit)
    const targetStagesTotal = Math.max(0, roundTo2(grandTotal - deductDeposit));
    const totalPaidVal = stages.reduce((sum, s, idx) => s.isPaid ? sum + computedValues[idx] : sum, 0);
    const targetUnpaidSum = Math.max(0, roundTo2(targetStagesTotal - totalPaidVal));

    const unpaidIndices = stages.map((s, idx) => s.isPaid ? -1 : idx).filter(i => i !== -1);
    if (unpaidIndices.length > 0) {
      const currentUnpaidSum = roundTo2(unpaidIndices.reduce((sum, idx) => sum + computedValues[idx], 0));
      const delta = roundTo2(targetUnpaidSum - currentUnpaidSum);

      if (Math.abs(delta) > 0 && Math.abs(delta) < 500) {
        const lastUnpaidIdx = unpaidIndices[unpaidIndices.length - 1];
        computedValues[lastUnpaidIdx] = Math.max(0, roundTo2(computedValues[lastUnpaidIdx] + delta));
      }
    }

    const stageValues = stages.map((s, idx) => ({
      ...s,
      val: computedValues[idx]
    }));

    return {
      subtotal,
      grandTotal,
      contractTotalBeforeDeposit,
      deductDeposit,
      depositVal,
      progressVal,
      balanceVal,
      stageValues
    };
  };

  const getVOFinancials = (input: VariationOrder | Quotation) => {
    const roundTo2 = (num: number) => Math.round(num * 100) / 100;
    let items: QuotationItem[] = [];
    let discount = 0;
    let stages: PaymentStage[] = [];
    
    if (!input) {
      return { subtotal: 0, grandTotal: 0, stageValues: [] };
    }
    
    if ('customerName' in input) {
      if (!input.hasVO) {
        return { subtotal: 0, grandTotal: 0, stageValues: [] };
      }
      items = input.voItems || [];
      discount = input.voDiscount || 0;
      stages = input.voPaymentStages || [];
    } else {
      items = input.items || [];
      discount = input.discount || 0;
      stages = input.paymentStages || [];
    }

    const subtotal = roundTo2(items.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0));
    const grandTotal = Math.max(0, roundTo2(subtotal - discount));
    
    const paidStagesInfo = stages.map((s, idx) => {
      const isPaid = !!s.isPaid;
      const fallbackVal = roundTo2(grandTotal * (s.percent / 100)) + (s.adjustmentAmount || 0);
      const lockedVal = isPaid ? (s.lockedAmount ?? fallbackVal) : null;
      return { index: idx, isPaid, lockedVal };
    });

    const totalLockedAmount = paidStagesInfo.reduce((sum, item) => sum + (item.lockedVal || 0), 0);
    const unpaidStages = stages.filter((_, idx) => !paidStagesInfo[idx].isPaid);
    const sumUnpaidPercents = unpaidStages.reduce((sum, s) => sum + s.percent, 0);

    const sumUnpaidAdjustments = unpaidStages.reduce((sum, s) => sum + (s.adjustmentAmount || 0), 0);

    const remainingToAllocate = roundTo2(grandTotal - totalLockedAmount);

    let cumulativeUnpaidAllocated = 0;
    let unpaidProcessedCount = 0;

    const stageValues = stages.map((s, idx) => {
      const paidInfo = paidStagesInfo[idx];
      if (paidInfo.isPaid) {
        return { ...s, val: roundTo2(paidInfo.lockedVal as number) };
      } else {
        unpaidProcessedCount++;
        let val = 0;
        const basePoolToAllocate = roundTo2(remainingToAllocate - sumUnpaidAdjustments);

        if (sumUnpaidPercents <= 0) {
          if (unpaidProcessedCount === unpaidStages.length) {
            val = Math.max(0, roundTo2(remainingToAllocate - cumulativeUnpaidAllocated));
          } else {
            const baseAlloc = roundTo2(basePoolToAllocate / Math.max(1, unpaidStages.length));
            val = Math.max(0, roundTo2(baseAlloc + (s.adjustmentAmount || 0)));
            cumulativeUnpaidAllocated += val;
          }
        } else {
          if (unpaidProcessedCount === unpaidStages.length) {
            val = Math.max(0, roundTo2(remainingToAllocate - cumulativeUnpaidAllocated));
          } else {
            const baseAlloc = roundTo2(basePoolToAllocate * (s.percent / sumUnpaidPercents));
            val = Math.max(0, roundTo2(baseAlloc + (s.adjustmentAmount || 0)));
            cumulativeUnpaidAllocated += val;
          }
        }
        return { ...s, val };
      }
    });

    return {
      subtotal,
      grandTotal,
      stageValues
    };
  };

  const getCombinedVOFinancials = (quote: Quotation) => {
    const migrated = migrateQuotation(quote);
    const vos = migrated.variationOrders || [];
    
    let subtotal = 0;
    let grandTotal = 0;
    const stageValues: (PaymentStage & { val: number; voId: string; stageIdx: number })[] = [];
    
    vos.forEach(vo => {
      const voFin = getVOFinancials(vo);
      subtotal += voFin.subtotal;
      grandTotal += voFin.grandTotal;
      voFin.stageValues.forEach((s, sIdx) => {
        stageValues.push({
          ...s,
          name: `[${vo.title}] ${s.name}`,
          voId: vo.id,
          stageIdx: sIdx
        });
      });
    });
    
    return {
      subtotal,
      grandTotal,
      stageValues
    };
  };

  // --- ACCOUNTANT PROGRESS CALCULATIONS ---
  const paymentContracts = useMemo(() => {
    const list = quotations.filter(q => ['signed', 'constructing', 'finished', 'completed'].includes(q.status));
    // Stable sort by ID descending (newest first) safely
    return list.sort((a, b) => (b.id || '').localeCompare(a.id || ''));
  }, [quotations]);

  const filteredPaymentContracts = useMemo(() => {
    return paymentContracts.filter(q => {
      // 1. Search Query Filter
      const lowerQuery = searchQuery.trim().toLowerCase();
      const assignedUser = accountsList.find(a => a.username === q.assignedTo);
      const assignedName = assignedUser ? assignedUser.displayName : (q.assignedTo || '');

      const matchSearch = !lowerQuery || 
        (q.customerName || '').toLowerCase().includes(lowerQuery) ||
        (q.phone || '').includes(lowerQuery) ||
        (q.address || '').toLowerCase().includes(lowerQuery) ||
        (q.id || '').toLowerCase().includes(lowerQuery) ||
        (q.internalNumber && (q.internalNumber || '').toLowerCase().includes(lowerQuery)) ||
        (q.assignedTo || '').toLowerCase().includes(lowerQuery) ||
        assignedName.toLowerCase().includes(lowerQuery);
        
      if (!matchSearch) return false;

      // 2. Outstanding Balance Filter
      const { grandTotal, stageValues, deductDeposit } = getQuoteFinancials(q);
      const collectedVal = stageValues.reduce((sum, s) => s.isPaid ? sum + s.val : sum, 0) + (deductDeposit || 0);
      const isFullyPaid = grandTotal > 0 && collectedVal >= grandTotal;

      if (paymentOutstandingFilter === 'outstanding') {
        return !isFullyPaid;
      } else if (paymentOutstandingFilter === 'fully_paid') {
        return isFullyPaid;
      }
      
      return true;
    });
  }, [paymentContracts, searchQuery, paymentOutstandingFilter]);

  const paymentStats = useMemo(() => {
    let totalContractValue = 0;
    let totalCollected = 0;
    let totalUncollected = 0;
    let totalStagesCount = 0;
    let uncollectedStagesCount = 0;

    paymentContracts.forEach(q => {
      const { grandTotal: originalGrandTotal, stageValues: originalStageValues, deductDeposit: originalDeductDeposit } = getQuoteFinancials(q);
      const voFinancials = getCombinedVOFinancials(q);
      const voGrandTotal = voFinancials.grandTotal;
      const voStageValues = voFinancials.stageValues;

      const grandTotal = originalGrandTotal + (q.hasVO ? voGrandTotal : 0);
      const stageValues = [...originalStageValues, ...(q.hasVO ? voStageValues : [])];

      totalContractValue += grandTotal;
      if (originalDeductDeposit > 0) {
        totalCollected += originalDeductDeposit;
      }
      
      stageValues.forEach(stage => {
        totalStagesCount++;
        if (stage.isPaid) {
          totalCollected += stage.val;
        } else {
          totalUncollected += stage.val;
          uncollectedStagesCount++;
        }
      });
    });

    return {
      totalContractValue,
      totalCollected,
      totalUncollected,
      totalStagesCount,
      uncollectedStagesCount
    };
  }, [paymentContracts]);

  const handleTogglePaymentStagePaid = async (quote: Quotation, stageIndex: number) => {
    if (!hasPermission(currentUser, 'feat_confirm_payments')) {
      showToast('æ‚¨æ²’æœ‰ç¢ºèªæ”¶æ¬¾èˆ‡å°å¸³çš„æ¬Šé™', 'error');
      return;
    }
    const currentStages = getPaymentStages(quote);
    const stage = currentStages[stageIndex];
    if (!stage) return;

    const financials = getQuoteFinancials(quote);
    const calculatedStage = financials.stageValues[stageIndex];
    const stageVal = calculatedStage ? calculatedStage.val : Math.round(financials.grandTotal * (stage.percent / 100));

    if (!stage.isPaid) {
      setPaymentConfirmModal({
        isOpen: true,
        quote,
        stageIndex,
        isVO: false,
        stageName: stage.name,
        expectedAmount: stageVal,
        receivedAmount: stageVal,
      });
    } else {
      showConfirm(
        'ç¢ºèªå–æ¶ˆã€Œå·²ä»˜æ¬¾ã€ç‹€æ…‹',
        `ç¢ºå®šè¦å°‡ã€Œ${quote.customerName}ã€çš„ã€${stage.name}ã€‘æ¬¾é …å–æ¶ˆæ”¶æ¬¾ç‹€æ…‹ï¼Œä¸¦è®Šæ›´å›ã€Œæœªä»˜æ¬¾ã€å—ï¼Ÿ\n\nğŸ’¡ ç³»çµ±å°‡è‡ªå‹•æ¸…é™¤ç•¶æœŸèˆ‡ä¸‹ä¸€æœŸçš„æ”¶æ¬¾èª¿æ•´èˆ‡ä»˜æ¬¾æ—¥æœŸå‚™è¨»ã€‚`,
        async () => {
          const updatedStages = currentStages.map((s, idx) => {
            if (idx === stageIndex) {
              let newRemark = s.remark || '';
              newRemark = newRemark.replace(/\s*\(ä»˜æ¬¾æ—¥æœŸ:\s*\d{4}-\d{2}-\d{2}\)/g, '');
              newRemark = newRemark.replace(/\s*\(å¯¦æ”¶\s*HK\$[\d,.]+,.*?\)/g, '');
              return { ...s, isPaid: false, remark: newRemark, lockedAmount: undefined };
            }
            if (idx === stageIndex + 1) {
              let nextRemark = s.remark || '';
              nextRemark = nextRemark.replace(/\s*\(ä¸ŠæœŸèª¿æ•´:.*?\)/g, '');
              return { ...s, adjustmentAmount: undefined, remark: nextRemark };
            }
            return s;
          });

          const updatedQuote: Quotation = {
            ...quote,
            paymentStages: updatedStages,
            updatedAt: Date.now()
          };

          try {
            await saveQuotationToFirestore(updatedQuote);
            showToast(`å·²æˆåŠŸå–æ¶ˆã€Œ${quote.customerName}ã€ä¹‹æ”¶æ¬¾ç‹€æ…‹`);
          } catch (err) {
            console.error("Firestore save error on payment untoggle:", err);
            showToast('åŒæ­¥è‡³é›²ç«¯æ™‚ç™¼ç”ŸéŒ¯èª¤', 'error');
          }
        },
        'ç¢ºå®šè®Šæ›´',
        'å–æ¶ˆ'
      );
    }
  };

  const handleToggleVOPaymentStagePaid = async (quote: Quotation, flatStageIndex: number) => {
    if (!hasPermission(currentUser, 'feat_confirm_payments')) {
      showToast('æ‚¨æ²’æœ‰ç¢ºèªæ”¶æ¬¾èˆ‡å°å¸³çš„æ¬Šé™', 'error');
      return;
    }
    const migrated = migrateQuotation(quote);
    const voFinancials = getCombinedVOFinancials(migrated);
    const clickedStage = voFinancials.stageValues[flatStageIndex];
    if (!clickedStage) return;

    const { voId, stageIdx } = clickedStage as any;
    const targetVo = (migrated.variationOrders || []).find(v => v.id === voId);
    if (!targetVo) return;

    const voFin = getVOFinancials(targetVo);
    const calculatedStage = voFin.stageValues[stageIdx];
    const stageVal = calculatedStage ? calculatedStage.val : Math.round(voFin.grandTotal * (clickedStage.percent / 100));

    if (!clickedStage.isPaid) {
      setPaymentConfirmModal({
        isOpen: true,
        quote: migrated,
        stageIndex: flatStageIndex,
        isVO: true,
        voId,
        voStageIdx: stageIdx,
        stageName: clickedStage.name,
        expectedAmount: stageVal,
        receivedAmount: stageVal,
      });
    } else {
      showConfirm(
        'ç¢ºèªå–æ¶ˆã€Œå·²ä»˜æ¬¾ (å¾ŒåŠ )ã€ç‹€æ…‹',
        `ç¢ºå®šè¦å°‡ã€Œ${migrated.customerName}ã€çš„å¾ŒåŠ é …ç›®ã€${clickedStage.name}ã€‘æ¬¾é …å–æ¶ˆæ”¶æ¬¾ç‹€æ…‹ï¼Œä¸¦è®Šæ›´å›ã€Œæœªä»˜æ¬¾ã€å—ï¼Ÿ\n\nğŸ’¡ ç³»çµ±å°‡è‡ªå‹•æ¸…é™¤ç•¶æœŸèˆ‡ä¸‹ä¸€æœŸçš„æ”¶æ¬¾èª¿æ•´èˆ‡ä»˜æ¬¾æ—¥æœŸå‚™è¨»ã€‚`,
        async () => {
          const updatedVos = (migrated.variationOrders || []).map(vo => {
            if (vo.id === voId) {
              const updatedStages = (vo.paymentStages || []).map((s, idx) => {
                if (idx === stageIdx) {
                  let newRemark = s.remark || '';
                  newRemark = newRemark.replace(/\s*\(ä»˜æ¬¾æ—¥æœŸ:\s*\d{4}-\d{2}-\d{2}\)/g, '');
                  newRemark = newRemark.replace(/\s*\(å¯¦æ”¶\s*HK\$[\d,.]+,.*?\)/g, '');
                  return { ...s, isPaid: false, remark: newRemark, lockedAmount: undefined };
                }
                if (idx === stageIdx + 1) {
                  let nextRemark = s.remark || '';
                  nextRemark = nextRemark.replace(/\s*\(ä¸ŠæœŸèª¿æ•´:.*?\)/g, '');
                  return { ...s, adjustmentAmount: undefined, remark: nextRemark };
                }
                return s;
              });
              return { ...vo, paymentStages: updatedStages };
            }
            return vo;
          });

          const legacyVoIndex = updatedVos.findIndex(v => v.id === 'vo-1');
          const legacyVo = legacyVoIndex >= 0 ? updatedVos[legacyVoIndex] : null;

          const updatedQuote: Quotation = {
            ...migrated,
            variationOrders: updatedVos,
            voPaymentStages: legacyVo ? legacyVo.paymentStages : migrated.voPaymentStages,
            updatedAt: Date.now()
          };

          try {
            await saveQuotationToFirestore(updatedQuote);
            showToast(`å·²æˆåŠŸå–æ¶ˆã€Œ${migrated.customerName}ã€å¾ŒåŠ ä¹‹æ”¶æ¬¾ç‹€æ…‹`);
          } catch (err) {
            console.error("Firestore save error on VO payment untoggle:", err);
            showToast('åŒæ­¥è‡³é›²ç«¯æ™‚ç™¼ç”ŸéŒ¯èª¤', 'error');
          }
        },
        'ç¢ºå®šè®Šæ›´',
        'å–æ¶ˆ'
      );
    }
  };

  const handleConfirmStageReceivedAmount = async (receivedAmt: number) => {
    if (!paymentConfirmModal) return;
    const { quote, stageIndex, isVO, voId, voStageIdx, expectedAmount, stageName } = paymentConfirmModal;
    
    const d = new Date();
    const todayStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    const diff = receivedAmt - expectedAmount;

    // Build stage-level log messages
    let currentStageDetail = ` (ä»˜æ¬¾æ—¥æœŸ: ${todayStr})`;
    if (diff > 0) {
      currentStageDetail = ` (ä»˜æ¬¾æ—¥æœŸ: ${todayStr}) (å¯¦æ”¶ HK$${receivedAmt.toLocaleString('en-US')}, æ‡‰æ”¶ HK$${expectedAmount.toLocaleString('en-US')}, æº¢æ”¶ HK$${diff.toLocaleString('en-US')} å·²è½‰å…¥ä¸‹æœŸæ‰£é™¤)`;
    } else if (diff < 0) {
      currentStageDetail = ` (ä»˜æ¬¾æ—¥æœŸ: ${todayStr}) (å¯¦æ”¶ HK$${receivedAmt.toLocaleString('en-US')}, æ‡‰æ”¶ HK$${expectedAmount.toLocaleString('en-US')}, æ¬ æ”¶ HK$${Math.abs(diff).toLocaleString('en-US')} å·²è½‰å…¥ä¸‹æœŸåŠ å›)`;
    } else {
      currentStageDetail = ` (ä»˜æ¬¾æ—¥æœŸ: ${todayStr}) (å¯¦æ”¶ HK$${receivedAmt.toLocaleString('en-US')}, æ‡‰æ”¶ HK$${expectedAmount.toLocaleString('en-US')})`;
    }

    // Build global/internal notes log
    const logHeader = `\n[æ”¶æ¬¾ç´€éŒ„ ${todayStr}] ã€${stageName}ã€‘`;
    const logBody = diff > 0 
      ? ` æ‡‰æ”¶: HK$${expectedAmount.toLocaleString('en-US')}, å¯¦æ”¶: HK$${receivedAmt.toLocaleString('en-US')}ã€‚æº¢æ”¶ HK$${diff.toLocaleString('en-US')} å·²å®‰æ’æ–¼ä¸‹ä¸€æœŸæ‰£é™¤ã€‚`
      : diff < 0
        ? ` æ‡‰æ”¶: HK$${expectedAmount.toLocaleString('en-US')}, å¯¦æ”¶: HK$${receivedAmt.toLocaleString('en-US')}ã€‚æ¬ æ”¶ HK$${Math.abs(diff).toLocaleString('en-US')} å·²å®‰æ’æ–¼ä¸‹ä¸€æœŸåŠ å›ã€‚`
        : ` æ‡‰æ”¶: HK$${expectedAmount.toLocaleString('en-US')}, å¯¦æ”¶: HK$${receivedAmt.toLocaleString('en-US')} (å…¨æ•¸æ”¶è¨–)ã€‚`;
    const newLogEntry = logHeader + logBody;

    let updatedQuote: Quotation = { ...quote };

    if (!isVO) {
      const currentStages = getPaymentStages(quote);
      const updatedStages = currentStages.map((s, idx) => {
        if (idx === stageIndex) {
          let newRemark = s.remark || '';
          newRemark = newRemark.replace(/\s*\(ä»˜æ¬¾æ—¥æœŸ:\s*\d{4}-\d{2}-\d{2}\)/g, '');
          newRemark = newRemark.replace(/\s*\(å¯¦æ”¶\s*HK\$[\d,.]+,.*?\)/g, '');
          newRemark = newRemark.trim() + currentStageDetail;
          return { ...s, isPaid: true, remark: newRemark, lockedAmount: receivedAmt };
        }
        if (idx === stageIndex + 1) {
          // Carry forward adjustment
          const nextAdj = (s.adjustmentAmount || 0) - diff;
          let nextRemark = s.remark || '';
          nextRemark = nextRemark.replace(/\s*\(ä¸ŠæœŸèª¿æ•´:.*?\)/g, '');
          if (diff !== 0) {
            const adjDetail = diff > 0 
              ? ` (ä¸ŠæœŸèª¿æ•´: æ‰£é™¤æº¢æ”¶ HK$${diff.toLocaleString('en-US')})`
              : ` (ä¸ŠæœŸèª¿æ•´: åŠ å›æ¬ æ”¶ HK$${Math.abs(diff).toLocaleString('en-US')})`;
            nextRemark = nextRemark.trim() + adjDetail;
          } else {
            nextRemark = nextRemark.trim();
          }
          return { ...s, adjustmentAmount: nextAdj, remark: nextRemark };
        }
        return s;
      });

      updatedQuote = {
        ...quote,
        paymentStages: updatedStages,
        draftRemarks: (quote.draftRemarks || '').trim() + newLogEntry,
        updatedAt: Date.now()
      };
    } else {
      // VO logic
      const migrated = migrateQuotation(quote);
      const updatedVos = (migrated.variationOrders || []).map(vo => {
        if (vo.id === voId) {
          const updatedStages = (vo.paymentStages || []).map((s, idx) => {
            if (idx === voStageIdx) {
              let newRemark = s.remark || '';
              newRemark = newRemark.replace(/\s*\(ä»˜æ¬¾æ—¥æœŸ:\s*\d{4}-\d{2}-\d{2}\)/g, '');
              newRemark = newRemark.replace(/\s*\(å¯¦æ”¶\s*HK\$[\d,.]+,.*?\)/g, '');
              newRemark = newRemark.trim() + currentStageDetail;
              return { ...s, isPaid: true, remark: newRemark, lockedAmount: receivedAmt };
            }
            if (idx === (voStageIdx as number) + 1) {
              const nextAdj = (s.adjustmentAmount || 0) - diff;
              let nextRemark = s.remark || '';
              nextRemark = nextRemark.replace(/\s*\(ä¸ŠæœŸèª¿æ•´:.*?\)/g, '');
              if (diff !== 0) {
                const adjDetail = diff > 0 
                  ? ` (ä¸ŠæœŸèª¿æ•´: æ‰£é™¤æº¢æ”¶ HK$${diff.toLocaleString('en-US')})`
                  : ` (ä¸ŠæœŸèª¿æ•´: åŠ å›æ¬ æ”¶ HK$${Math.abs(diff).toLocaleString('en-US')})`;
                nextRemark = nextRemark.trim() + adjDetail;
              } else {
                nextRemark = nextRemark.trim();
              }
              return { ...s, adjustmentAmount: nextAdj, remark: nextRemark };
            }
            return s;
          });
          return { ...vo, paymentStages: updatedStages };
        }
        return vo;
      });

      const legacyVoIndex = updatedVos.findIndex(v => v.id === 'vo-1');
      const legacyVo = legacyVoIndex >= 0 ? updatedVos[legacyVoIndex] : null;

      updatedQuote = {
        ...migrated,
        variationOrders: updatedVos,
        voPaymentStages: legacyVo ? legacyVo.paymentStages : migrated.voPaymentStages,
        draftRemarks: (migrated.draftRemarks || '').trim() + newLogEntry,
        updatedAt: Date.now()
      };
    }

    // Instantly close modal and update local state for zero-latency UI response
    setPaymentConfirmModal(null);
    setQuotations(prev => prev.map(q => q.id === updatedQuote.id ? updatedQuote : q));

    try {
      await saveQuotationToFirestore(updatedQuote);
      showToast(`å·²æˆåŠŸç™»è¨˜ã€Œ${quote.customerName}ã€ä¹‹å¯¦æ”¶é‡‘é¡ä¸¦èª¿æ•´ä¸‹æœŸæ”¶æ¬¾é …ç›®`);
    } catch (err) {
      console.error("Firestore save error on confirming received amount:", err);
      showToast('åŒæ­¥è‡³é›²ç«¯æ™‚ç™¼ç”ŸéŒ¯èª¤', 'error');
    }
  };

